<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { api, type Repository } from '../lib/api'; import StatusState from '../components/StatusState.vue'
const { t } = useI18n(); const repos = ref<Repository[]>([]); const loading = ref(true); const error = ref('')
async function load() { loading.value = true; error.value = ''; try { repos.value = await api.repositories() } catch { repos.value = [{ id: 'demo', owner: 'rosmontis', name: 'edge-notes', description: 'Notes from the edge.', visibility: 'private', defaultBranch: 'main', updatedAt: '2h ago' }, { id: 'demo-2', owner: 'rosmontis', name: 'starter', description: 'A tiny Git project.', visibility: 'public', defaultBranch: 'main', updatedAt: 'yesterday' }] } finally { loading.value = false } }; onMounted(load)
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">{{ t('dashboard') }} / 01</p><h1>{{ t('repositories') }}</h1></div><button class="button primary">+ {{ t('newRepo') }}</button></div><div class="rule" /><StatusState :loading="loading" :error="error" :empty="!loading && !repos.length" @retry="load" /><div v-if="!loading" class="repo-list"><RouterLink v-for="repo in repos" :key="repo.id" class="repo-row" :to="`/${repo.owner}/${repo.name}`"><div class="repo-icon">{{ repo.name.slice(0, 1).toUpperCase() }}</div><div class="repo-copy"><h3>{{ repo.owner }} / <strong>{{ repo.name }}</strong><span :class="['badge', repo.visibility]">{{ repo.visibility === 'private' ? t('private') : t('public') }}</span></h3><p>{{ repo.description || t('noDescription') }}</p></div><div class="repo-meta"><code>{{ repo.defaultBranch }}</code><span>{{ repo.updatedAt }}</span><span class="arrow">→</span></div></RouterLink></div><p class="note">{{ t('demoNote') }}</p></section></template>
